(5535858, 799259, 62187, '<td valign="top">Certainly one of the most creative photos of the challenge and professionally photographed as well.</td>', 'Certainly one of the most creative photos of the challenge and professionally photographed as well.', '2009-06-19 00:21:22.000000', NULL, 1),
