(5537323, 800004, 62187, '<td valign="top">A very nice try and something unconventional for the challenge.</td>', 'A very nice try and something unconventional for the challenge.', '2009-06-20 11:51:51.000000', NULL, 1),
(5537324, 799806, 62187, '<td valign="top">Something about your title made me think it was toys. It it''s not toys, you''ve certainly made me wonder and that''s good huh!?!?!?! The focus is very sharp.</td>', 'Something about your title made me think it was toys. It it''s not toys, you''ve certainly made me wonder and that''s good huh!?!?!?! The focus is very sharp.', '2009-06-20 12:01:34.000000', NULL, 1),
(5537325, 800026, 62187, '<td valign="top">What an interesting building! I''m seeing some slight haloing around the crane and some noise in the sky. But, it''s an awesome find for this challenge.</td>', 'What an interesting building! I''m seeing some slight haloing around the crane and some noise in the sky. But, it''s an awesome find for this challenge.', '2009-06-20 12:03:44.000000', NULL, 1),
(5537327, 799096, 62187, '<td valign="top">I love the idea but I fear it may not go so well with most voters.</td>', 'I love the idea but I fear it may not go so well with most voters.', '2009-06-20 12:04:36.000000', NULL, 1),
(5537328, 798773, 62187, '<td valign="top">I like the colors and maybe a tad bit oversharpened. A nice composition.</td>', 'I like the colors and maybe a tad bit oversharpened. A nice composition.', '2009-06-20 12:04:41.000000', NULL, 1),
(5537329, 799984, 62187, '<td valign="top">Excellent focus and my favorite NASCAR drivers'' sponsor!</td>', 'Excellent focus and my favorite NASCAR drivers'' sponsor!', '2009-06-20 12:06:10.000000', NULL, 1),
(5537330, 799949, 62187, '<td valign="top">It''s like a I want to see a wider view but as is, it''s just enough to make it ''mysterious''. I really like the drab, low lighting in this photo and the contrast of the brighter sky.</td>', 'It''s like a I want to see a wider view but as is, it''s just enough to make it ''mysterious''. I really like the drab, low lighting in this photo and the contrast of the brighter sky.', '2009-06-20 12:10:23.000000', NULL, 1),
(5537331, 799475, 62187, '<td valign="top">The focus looks good and not seeing much noise for a darker shot: good job.</td>', 'The focus looks good and not seeing much noise for a darker shot: good job.', '2009-06-20 12:11:43.000000', NULL, 1),
(5537332, 800020, 62187, '<td valign="top">Super good focus!</td>', 'Super good focus!', '2009-06-20 12:12:00.000000', NULL, 1),
(5537334, 799413, 62187, '<td valign="top">You''re right about that: especially these days.</td>', 'You''re right about that: especially these days.', '2009-06-20 12:14:59.000000', NULL, 1),
(5537335, 799808, 62187, '<td valign="top">A nice find and composition. Looks to me to be slightly oversharpened (?)</td>', 'A nice find and composition. Looks to me to be slightly oversharpened (?)', '2009-06-20 12:16:18.000000', NULL, 1),
(5537336, 799272, 62187, '<td valign="top">Great idea to use the window as the frame. The color of it is maybe a little distracting and might have been better without. ? The focus is very sharp and crisp.</td>', 'Great idea to use the window as the frame. The color of it is maybe a little distracting and might have been better without. ? The focus is very sharp and crisp.', '2009-06-20 12:17:35.000000', NULL, 1),
(5537337, 799991, 62187, '<td valign="top">Kind of shoehornish but wow, I sure wish they''d finish up with all the road work in my town!</td>', 'Kind of shoehornish but wow, I sure wish they''d finish up with all the road work in my town!', '2009-06-20 12:18:32.000000', NULL, 1),
(5537486, 799546, 98339, '<td valign="top">I really like the bright colors in this...well done</td>', 'I really like the bright colors in this...well done', '2009-06-20 13:42:22.000000', NULL, 1),
(5537487, 799994, 83773, '<td valign="top">nice! very Escher!</td>', 'nice! very Escher!', '2009-06-20 13:44:08.000000', NULL, 1),
(5537488, 799873, 83773, '<td valign="top">lol</td>', 'lol', '2009-06-20 13:44:26.000000', NULL, 1),
(5537489, 799176, 83773, '<td valign="top">nice interpretation of the challenge.</td>', 'nice interpretation of the challenge.', '2009-06-20 13:45:20.000000', NULL, 1),
(5537490, 799901, 83773, '<td valign="top">It is kind of eery isn''t it. The clouds are really cool in this... very foreboding.</td>', 'It is kind of eery isn''t it. The clouds are really cool in this... very foreboding.', '2009-06-20 13:46:03.000000', NULL, 1),
