(5537730, 799901, 51747, '<td valign="top">Nice sky here. Sad story if those are all abandoned construction sites.</td>', 'Nice sky here. Sad story if those are all abandoned construction sites.', '2009-06-20 16:57:15.000000', NULL, 1),
