(5537911, 799808, 38162, '<td valign="top">rule of thirds composition (or perhaps a square, cropping out much of that sky) would have made this one a winner.</td>', 'rule of thirds composition (or perhaps a square, cropping out much of that sky) would have made this one a winner.', '2009-06-20 21:08:38.000000', NULL, 1),
