(5541967, 799085, 20927, '<td valign="top">Now is post factum: i have cut construction and have left just pattern :(  <br/></td>', 'Now is post factum: i have cut construction and have left just pattern :(  ', '2009-06-24 08:19:40.000000', NULL, 0),
(5541971, 800040, 103032, '<td valign="top">This was in my top three picks for this challenge.  I think this caught the essence of a working job site at night.  Thought it would ribbon.  Nice work anyways.</td>', 'This was in my top three picks for this challenge.  I think this caught the essence of a working job site at night.  Thought it would ribbon.  Nice work anyways.', '2009-06-24 08:24:58.000000', NULL, 0),
(5541975, 799938, 103032, '<td valign="top">Congrats on a top ten and your personal best.  This was my fav.  I was sure this was gonna be a blue.  Anyways, this is an awesome shot, this is construction.</td>', 'Congrats on a top ten and your personal best.  This was my fav.  I was sure this was gonna be a blue.  Anyways, this is an awesome shot, this is construction.', '2009-06-24 08:40:44.000000', NULL, 0),
(5541980, 798708, 67697, '<td valign="top">That sky is definitely gorgeous.  Congrats on your first blue!</td>', 'That sky is definitely gorgeous.  Congrats on your first blue!', '2009-06-24 08:47:54.000000', NULL, 0),
(5541982, 799972, 67697, '<td valign="top">I like how you framed the city in there on the left.  Pretty sky.  Congrats on 2nd place!</td>', 'I like how you framed the city in there on the left.  Pretty sky.  Congrats on 2nd place!', '2009-06-24 08:48:49.000000', NULL, 0),
(5541987, 799761, 67697, '<td valign="top">I''m surprised this does not excite you.  I find this fascinating... maybe because it is the subject.  I bet it is really interesting to watch this type of construction going on in person.  Visually, my fave part is the water.  It looks like slick glass.  Congrats on the top 10!</td>', 'I''m surprised this does not excite you.  I find this fascinating... maybe because it is the subject.  I bet it is really interesting to watch this type of construction going on in person.  Visually, my fave part is the water.  It looks like slick glass.  Congrats on the top 10!', '2009-06-24 08:51:12.000000', NULL, 0),
(5541997, 799938, 67697, '<td valign="top">Look at you - you are on a roll!  Such an interesting moment captured.  I''m amazed at people who can do work like this, especially being able to hold their balance like that.  How far off the ground was he?  Congrats on the top 10 and a new PB!!</td>', 'Look at you - you are on a roll!  Such an interesting moment captured.  I''m amazed at people who can do work like this, especially being able to hold their balance like that.  How far off the ground was he?  Congrats on the top 10 and a new PB!!', '2009-06-24 08:53:56.000000', NULL, 0),
(5542006, 798829, 67697, '<td valign="top">This is a fun shot to add to the family collection.  The house looks great!  Love the porch - looks like it''s going to be a great place to hang out.  I like the light shining on the house - looks almost like a spotlight.  Good luck on the move!</td>', 'This is a fun shot to add to the family collection.  The house looks great!  Love the porch - looks like it''s going to be a great place to hang out.  I like the light shining on the house - looks almost like a spotlight.  Good luck on the move!', '2009-06-24 08:56:25.000000', NULL, 0),
(5542071, 799728, 73235, '<td valign="top">great pic, first entry - top 5. congrats, Mark</td>', 'great pic, first entry - top 5. congrats, Mark', '2009-06-24 09:32:40.000000', NULL, 0),
(5542220, 798708, 107827, '<td valign="top">We get skies like that here, especially in winter! It makes you appreciate it more when its not a year round, every day kind of thing. Good catch, beautiful pic!</td>', 'We get skies like that here, especially in winter! It makes you appreciate it more when its not a year round, every day kind of thing. Good catch, beautiful pic!', '2009-06-24 11:00:29.000000', NULL, 0),
(5542228, 799942, 107827, '<td valign="top">This was my personal fave... My 10 was instant. This pic gave a great feeling. Congrats on the capture!</td>', 'This was my personal fave... My 10 was instant. This pic gave a great feeling. Congrats on the capture!', '2009-06-24 11:02:29.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5542259, 799761, 100727, '<td valign="top">Hello Andrew, congratulations to you too.  Once the place is completed, you will have more things to shoot :)</td>', 'Hello Andrew, congratulations to you too.  Once the place is completed, you will have more things to shoot :)', '2009-06-24 11:16:37.000000', NULL, 0),
(5542331, 798805, 83026, '<td valign="top">Yay! A fellow Malaysian winning, represent!</td>', 'Yay! A fellow Malaysian winning, represent!', '2009-06-24 12:32:22.000000', NULL, 0),
(5542334, 800040, 102645, '<td valign="top">Thanks for the comments.<br/> <br/>I did notice after I uploaded that the exposure did seem a bit much.  It''s funny that when I looked at it in photoshop, it seemed reasonable.  However in a browser it looks a bit worse.<br/> <br/>Also, mixed reviews about the guy in the photo.  I was considering not having him in there but thought it would help with the scale.  Even with him in there, the picture doesn''t quite capture the grandeur of this site.  <br/> <br/>Checked my score earlier in the day and was about .5 off my personal best.  Miraculously, it surpassed my previous top score by the end of voting.  Thanks!!!</td>', 'Thanks for the comments. I did notice after I uploaded that the exposure did seem a bit much.  It''s funny that when I looked at it in photoshop, it seemed reasonable.  However in a browser it looks a bit worse. Also, mixed reviews about the guy in the photo.  I was considering not having him in there but thought it would help with the scale.  Even with him in there, the picture doesn''t quite capture the grandeur of this site.   Checked my score earlier in the day and was about .5 off my personal best.  Miraculously, it surpassed my previous top score by the end of voting.  Thanks!!!', '2009-06-24 12:33:14.000000', NULL, 0),
(5542345, 799728, 41066, '<td valign="top">I am just back on dpchallenge after a long break.  I see people are still giving he most amazing shots, scores of under 5.  Very Disappointing.  At some point people need to give up on their greed for their own scores and appreciate true art like this shot!  Congrats on such a fabulous job!</td>', 'I am just back on dpchallenge after a long break.  I see people are still giving he most amazing shots, scores of under 5.  Very Disappointing.  At some point people need to give up on their greed for their own scores and appreciate true art like this shot!  Congrats on such a fabulous job!', '2009-06-24 12:47:53.000000', NULL, 0),
(5542348, 799512, 61961, '<td valign="top">Congrats on your DQ -- I enjoyed your forum thread on the topic.</td>', 'Congrats on your DQ -- I enjoyed your forum thread on the topic.', '2009-06-24 12:50:51.000000', NULL, 0),
(5542460, 799259, 104091, '<td valign="top">I did notice this during voting on Twitter and reported it to SC as I was not sure if it was permissible or not as I couldnt find any reference on site. As the image was not DQed I''m assuming it is ok to do so.<br/> <br/>It is a nice image.<br/> <br/>&lt;Edit&gt; 25/06/09<br/>Sorry everyone,<br/> <br/>I have decided to leave the site.<br/> <br/>Unfortunately, what seems to me the unfair, challenge justice / injustice that is dealt out and blatant cheating that seems to go on by some has discouraged me from entering any future challenges.<br/> <br/>I say goodbye and wish you all the best for the future.<br/> <br/>I shall stay in touch with those of you that have become good friends.<br/> <br/>As I can not delete my account or images I leave my images and this message for prosperity. (Or at least until my subs run out!)<br/><br/><i>Message edited by author 2009-06-25 15:33:29.</i></td>', 'I did notice this during voting on Twitter and reported it to SC as I was not sure if it was permissible or not as I couldnt find any reference on site. As the image was not DQed I''m assuming it is ok to do so. It is a nice image. <Edit> 25/06/09Sorry everyone, I have decided to leave the site. Unfortunately, what seems to me the unfair, challenge justice / injustice that is dealt out and blatant cheating that seems to go on by some has discouraged me from entering any future challenges. I say goodbye and wish you all the best for the future. I shall stay in touch with those of you that have become good friends. As I can not delete my account or images I leave my images and this message for prosperity. (Or at least until my subs run out!)', '2009-06-24 14:00:59.000000', '2009-06-25 16:33:29.000000', 0),
(5542573, 798708, 24454, '<td valign="top">Whoa!  What a proud photo to be your first blue ribbon.  Construction never looked so amazing!</td>', 'Whoa!  What a proud photo to be your first blue ribbon.  Construction never looked so amazing!', '2009-06-24 15:13:17.000000', NULL, 0),
(5542578, 799728, 24454, '<td valign="top">Oh awesome!  You know why I love a photo like this doing so well and showing itself so proudly on the first page?  Not only is it an amazing photo!  But there was a time (before your time :) when the voting community decidedly let people know that it was <i>not</i> acceptable to think outside the box and submit something even so much as slightly out of the literal interpretation of the challenge.  Way to GO!  And I''m proud of our progressive thinking now. Congratulations on an honorable mention with this very impressive shot that fits the challenge to a T  :)<br/></td>', 'Oh awesome!  You know why I love a photo like this doing so well and showing itself so proudly on the first page?  Not only is it an amazing photo!  But there was a time (before your time :) when the voting community decidedly let people know that it was not acceptable to think outside the box and submit something even so much as slightly out of the literal interpretation of the challenge.  Way to GO!  And I''m proud of our progressive thinking now. Congratulations on an honorable mention with this very impressive shot that fits the challenge to a T  :)', '2009-06-24 15:20:46.000000', NULL, 0),
(5542584, 799761, 24454, '<td valign="top">Beeeeeautiful!  Just what one would expect from an AndrewT shot :)</td>', 'Beeeeeautiful!  Just what one would expect from an AndrewT shot :)', '2009-06-24 15:24:31.000000', NULL, 0),
(5542585, 799938, 24454, '<td valign="top">In my book, this is top 10 material no matter how many were in the challenge.  What drama!  I love it!<br/> <br/></td>', 'In my book, this is top 10 material no matter how many were in the challenge.  What drama!  I love it! ', '2009-06-24 15:25:50.000000', NULL, 0),
(5542586, 799259, 24454, '<td valign="top">This is so cute!  And I am so impressed with our voters in this challenge!  They have really rewarded some creative, outside the box thinking, and I love it!!  Congratulations on 8th place!<br/> <br/></td>', 'This is so cute!  And I am so impressed with our voters in this challenge!  They have really rewarded some creative, outside the box thinking, and I love it!!  Congratulations on 8th place! ', '2009-06-24 15:26:49.000000', NULL, 0),
(5542587, 799994, 24454, '<td valign="top">This is awesome!!</td>', 'This is awesome!!', '2009-06-24 15:27:20.000000', NULL, 0),
(5542588, 798829, 24454, '<td valign="top">Ooooooh, nice job, Jeffrey!  And such a personal, triumphant shot as you watch your hard worked-for house come to a reality right before your very eyes.  It looks like you are almost there :)<br/> <br/></td>', 'Ooooooh, nice job, Jeffrey!  And such a personal, triumphant shot as you watch your hard worked-for house come to a reality right before your very eyes.  It looks like you are almost there :) ', '2009-06-24 15:30:15.000000', NULL, 0),
